import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Security Agents","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/security-agents.md","filePath":"products/ai-coding/cursor/security-agents.md","lastUpdated":1787110548000}'),a={name:"products/ai-coding/cursor/security-agents.md"};function s(i,t,l,u,d,c){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="security-agents" tabindex="-1">Security Agents <a class="header-anchor" href="#security-agents" aria-label="Permalink to &quot;Security Agents&quot;">​</a></h1><p>Security Agents scan your code for <strong>security bugs, risky patterns, and vulnerabilities</strong>. They are Cursor-managed agents on <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Automations</a>, and they <strong>require Cloud Agents</strong>.</p><blockquote><p>Official: <a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>.</p><p>Two types: <strong>Security Reviewer</strong> (pull / merge requests) and <strong>Vulnerability Scanner</strong> (cron). Local skill: <code>/review-security</code>. Team usage pool — not your personal quota.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Cloud Agents available on the account (paid plan; admin has connected source control)</li><li>Access to <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Automations</a></li><li>Cursor <strong>3.7+</strong> if you want <code>/review-security</code> / <code>/review</code> in the editor or on <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a></li><li><strong>Team or Enterprise</strong> if another product (PR Routing) will consume Security Review Context</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Tell Security Reviewer apart from Vulnerability Scanner — and from Bugbot</li><li>Configure a trigger, at least one tool / MCP, and custom instructions</li><li>Run <code>/review-security</code> on your branch before you push</li><li>Know that usage is billed to the <strong>team pool</strong>, not to you</li></ol><hr><h2 id="two-agent-types" tabindex="-1">Two agent types <a class="header-anchor" href="#two-agent-types" aria-label="Permalink to &quot;Two agent types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Trigger</th><th>Job</th></tr></thead><tbody><tr><td><strong>Security Reviewer</strong></td><td>Git-based Automations triggers: pull request and merge request events</td><td>Catch vulnerabilities <strong>during</strong> code review</td></tr><tr><td><strong>Vulnerability Scanner</strong></td><td>Cron</td><td>Scan the codebase <strong>at rest</strong> — pre-existing issues, long-standing bugs, things PR review missed</td></tr></tbody></table><p>Both run on the Automations platform. Both need Cloud Agents. You can use Cursor&#39;s cloud with no extra VM setup.</p><p>This is <strong>not</strong> Bugbot. Bugbot reviews a PR diff for bugs / security / quality and comments. Security Agents are a separate Cursor-managed automation family. PR Routing can <strong>read</strong> both: <a href="./pr-routing.html">Bugbot Review Context</a> and Security Review Context.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Open <a href="https://cursor.com/automations/from-cursor/security" target="_blank" rel="noreferrer">Security Agents in Automations</a>.</p><ol><li>Pick <strong>Security Reviewer</strong> or <strong>Vulnerability Scanner</strong></li><li>Set <strong>triggers</strong> (PR / MR events vs cron)</li><li>Enable or disable built-in <strong>security checks</strong></li><li>Add <strong>custom instructions</strong>: what to prioritize, project-specific expectations, how the agent should behave</li><li>Attach <strong>tools and MCPs</strong> — each agent needs <strong>at least one</strong> tool or MCP to run</li><li>Save. Runs appear in Automations history</li></ol><p>Use tools / MCPs to send findings to Slack or an issue tracker, to tell the agent when to call each MCP, and to give extra context before it reports.</p><h2 id="run-in-your-agent" tabindex="-1">Run in your agent <a class="header-anchor" href="#run-in-your-agent" aria-label="Permalink to &quot;Run in your agent&quot;">​</a></h2><p>Use <code>/review-security</code> or <code>/review</code> <strong>before you push</strong>.</p><table tabindex="0"><thead><tr><th>Knob</th><th>Official default</th></tr></thead><tbody><tr><td><strong>What diff</strong></td><td>Your <strong>branch</strong> vs the base: committed <strong>and</strong> uncommitted changes</td></tr><tr><td><strong>Which base</strong></td><td>The default base branch. If that is not <code>main</code>, tell the agent which branch to compare, or let it infer</td></tr></tbody></table><p>Ask it to review <strong>only uncommitted</strong> changes when you want a narrower pass.</p><p><code>/review</code> and <code>/review-security</code> are available in <strong>Cursor 3.7+</strong> and at <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a>. <strong>CLI support is coming soon</strong> — do not document a working <code>agent /review-security</code> yet.</p><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><p>Security Agents are billed at the <strong>team usage</strong> level:</p><ul><li>Charged to the team&#39;s <strong>usage pool</strong></li><li>They run under a <strong>shared team service account</strong></li><li>They do <strong>not</strong> consume any individual user&#39;s usage</li></ul><p>Automations create Cloud Agents; see <a href="https://cursor.com/docs/models-and-pricing.md#model-pricing" target="_blank" rel="noreferrer">Cloud agent pricing</a> for the underlying model rates.</p><h2 id="analytics-and-runs" tabindex="-1">Analytics and runs <a class="header-anchor" href="#analytics-and-runs" aria-label="Permalink to &quot;Analytics and runs&quot;">​</a></h2><p>Three metrics across runs:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Vulnerabilities found</strong></td><td>Security findings reported</td></tr><tr><td><strong>Issues fixed</strong></td><td>Findings later resolved</td></tr><tr><td><strong>Resolution rate</strong></td><td>Percentage of reported findings that were fixed</td></tr></tbody></table><p>Cursor uses <strong>LLMs on incremental diffs</strong> to decide whether a flagged issue was actually fixed.</p><p>Every run is tracked in Automations: when it ran, which tools it used, final status, duration. Open a run to inspect the underlying Cloud Agent.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>PR gate: Security Reviewer on pull / merge request events</li><li>Recurring baseline: Vulnerability Scanner on a cron, independent of PR traffic</li><li>Local pre-push: <code>/review-security</code> on the current branch</li><li>Feed PR Routing: enable <strong>Security Review Context</strong> so low-risk auto-approve waits on these findings</li></ul><p>Stay on Bugbot alone when you want a general bug / quality pass, not a dedicated security agent.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>Treat this as Bugbot with a new name</td><td>Different product. Bugbot comments on a diff; this is a managed Security Agent</td></tr><tr><td>Forget a tool / MCP</td><td>Official: each agent needs <strong>at least one</strong> to run</td></tr><tr><td>Expect it on the CLI today</td><td>Official: <strong>CLI support is coming soon</strong></td></tr><tr><td>Assume it bills your personal quota</td><td>Team usage pool + shared service account</td></tr><tr><td>Ask <code>/review-security</code> for “only the last commit” without saying so</td><td>Default is <strong>the whole branch</strong>, committed and uncommitted</td></tr><tr><td>Skip Cloud Agents / source-control setup</td><td>These agents <strong>require</strong> Cloud Agents</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cloud-agents.html">Cloud Agents</a> — the runtime</li><li><a href="./pr-routing.html">PR Routing</a> — can wait on Security Review Context</li><li><a href="./cursor-cookbook.html#review-prs-with-bugbot">Cookbook · Bugbot</a> — general PR review</li><li>Official: <a href="https://cursor.com/docs/security-agents" target="_blank" rel="noreferrer">Security Agents</a>, <a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></li></ul>',38)])])}const f=e(a,[["render",s]]);export{b as __pageData,f as default};
